INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ICMPv6 nur für Fehlermeldungen da?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Diagnose wie Echo Request"}, {"text": "Ja", "correct": false, "because": "Unterschätzt Diagnosefunktionen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt ICMPv6 in einem Netzwerk?', 3, '[{"text": "Nachbarschaftserkennung", "correct": true, "because": "Ermöglicht Neighbor Discovery"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Nicht seine Aufgabe"}, {"text": "Routing-Optimierung", "correct": false, "because": "Routing ist IP-Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen übernimmt ICMPv6?', 5, '[{"text": "Echo Request/Reply", "correct": true, "because": "Testet Erreichbarkeit"}, {"text": "Neighbor Solicitation", "correct": true, "because": "Findet Geräte im Netz"}, {"text": "Paketkompression", "correct": false, "because": "Nicht ICMP-Aufgabe"}, {"text": "Bandbreitenmessung", "correct": false, "because": "Andere Tools"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) ICMPv6 ersetzt ARP. b) Es läuft auf Schicht 4.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schicht 3, nicht 4"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung von ICMPv6?', 4, '[{"text": "Echo Reply", "correct": false, "because": "Kern der Diagnose"}, {"text": "Neighbor Advertisement", "correct": false, "because": "Wichtig für NDP"}, {"text": "Datenpayload", "correct": true, "because": "ICMP ist steuerungsorientiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ICMPv6 verschlüsselt ist?', 2, '[{"text": "Nein", "correct": true, "because": "Klartext für Diagnose"}, {"text": "Ja", "correct": false, "because": "Keine Verschlüsselungsebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Paket sende ich, um Erreichbarkeit zu prüfen?', 3, '[{"text": "Echo Request", "correct": true, "because": "Fordert Reply an"}, {"text": "Router Solicitation", "correct": false, "because": "Für Routerabfrage"}, {"text": "Neighbor Advertisement", "correct": false, "because": "Antwort, kein Test"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben erledigt ICMPv6 im Netzwerk?', 5, '[{"text": "Geräteerkennung", "correct": true, "because": "Via Neighbor Discovery"}, {"text": "Erreichbarkeitstest", "correct": true, "because": "Echo Request/Reply"}, {"text": "Datenflusssteuerung", "correct": false, "because": "TCP-Aufgabe"}, {"text": "IP-Adresszuweisung", "correct": false, "because": "DHCPv6"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) ICMPv6 ist essenziell für IPv6. b) Es blockiert Pakete. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist Firewall-Aufgabe"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, wenn ich ICMPv6 nutze?', 4, '[{"text": "Echo Request", "correct": false, "because": "Kernfunktion"}, {"text": "Neighbor Solicitation", "correct": false, "because": "Für NDP nötig"}, {"text": "HTTP-Header", "correct": true, "because": "Andere Schicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ICMPv6 optional bei IPv6?', 2, '[{"text": "Nein", "correct": true, "because": "Pflicht für Diagnose"}, {"text": "Ja", "correct": false, "because": "Kernprotokoll"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Pakete helfen mir, Geräte im Netz zu finden?', 4, '[{"text": "Neighbor Solicitation", "correct": true, "because": "Fragt nach Nachbarn"}, {"text": "Echo Reply", "correct": false, "because": "Nur Antwort"}, {"text": "Router Advertisement", "correct": false, "because": "Router-Info"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ICMPv6 nur für Ping da ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch NDP und mehr"}, {"text": "Ja", "correct": false, "because": "Ping ist nur Teil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der ICMPv6-Diagnose?', 3, '[{"text": "Echo Request", "correct": true, "because": "Schnelle Erreichbarkeitsprüfung"}, {"text": "Paketgröße", "correct": false, "because": "Sekundär"}, {"text": "Routing-Tabellen", "correct": false, "because": "Andere Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) ICMPv6 nutzt Multicast. b) Es ersetzt TCP.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "TCP ist Transport"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ICMPv6?', 5, '[{"text": "Netzwerkdiagnose", "correct": true, "because": "Echo und mehr"}, {"text": "Geräteerkennung", "correct": true, "because": "Via NDP"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Nicht ICMP"}, {"text": "Bandbreitensteigerung", "correct": false, "because": "Netzwerkabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei ICMPv6 unwichtig?', 3, '[{"text": "Echo Reply", "correct": false, "because": "Diagnosekern"}, {"text": "Neighbor Discovery", "correct": false, "because": "Netzwerkfunktion"}, {"text": "Portnummern", "correct": true, "because": "Schicht 4, nicht ICMP"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Läuft ICMPv6 über UDP?', 3, '[{"text": "Nein", "correct": true, "because": "Direkt über IPv6"}, {"text": "Ja", "correct": false, "because": "Kein Transportprotokoll"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ICMPv6 Router findet?', 2, '[{"text": "Ja", "correct": true, "because": "Via Router Solicitation"}, {"text": "Nein", "correct": false, "because": "Teil von NDP"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachricht nutze ich, um Nachbarn zu identifizieren?', 4, '[{"text": "Neighbor Solicitation", "correct": true, "because": "Fragt nach MAC"}, {"text": "Echo Request", "correct": false, "because": "Nur Erreichbarkeit"}, {"text": "Router Advertisement", "correct": false, "because": "Router-Info"}]');
